# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces humanoïdes n’est pas un gobelinoïde ?','Kobold',['Gobelin','Hobgobelin','Gobelours'],'Les gobelinoïdes sont les gobelins, hobgobelins et gobelours. Le kobold est un humanoïde reptilien.',MM+', entrées correspondantes')
I(2,'Dans D&D 5e, lequel de ces dieux n’est pas un dieu de peuples « monstrueux » ?','Moradin',['Gruumsh','Maglubiyet','Kurtulmak'],'Moradin est le dieu des nains. Gruumsh (orques), Maglubiyet (gobelinoïdes) et Kurtulmak (kobolds) sont des dieux de monstres.',MM+' et Volo’s Guide to Monsters (2016)')
I(2,'Dans D&D 5e, lequel de ces humanoïdes ne vit pas près de l’eau ?','Gnoll',['Homme-lézard','Bullywug','Sahuagin'],'Le gnoll rôde dans les plaines et les déserts. Les trois autres vivent dans les marais ou en mer.',MM+', entrées correspondantes')
T(1,'Dans D&D 5e, les kobolds ont une sensibilité au ____.','soleil',['feu','froid','bruit'],'Les kobolds subissent un désavantage aux attaques et aux jets de Sagesse (Perception) en plein soleil.',MM+', entrée « Kobold »')
T(2,'Dans D&D 5e, les gnolls suivent le Seigneur démon ____.','Yeenoghu',['Orcus','Demogorgon','Baphomet'],'Yeenoghu, le Prince des bêtes, est le maître des gnolls.',MM+', entrée « Gnoll »')
T(3,'Dans D&D 5e, le trait ____ permet au hobgobelin d’infliger des dégâts supplémentaires si un allié est proche de sa cible.','Avantage martial',['Attaque sournoise','Tactique de meute','Rage'],'L’Avantage martial du hobgobelin ajoute 2d6 dégâts quand un allié non neutralisé est près de la cible.',MM+', entrée « Hobgobelin »')
M(1,'Dans D&D 5e, lesquels de ces monstres sont des gobelinoïdes ? (plusieurs bonnes réponses)',['Gobelin','Hobgobelin','Gobelours'],['Orque','Kobold'],'Gobelin, hobgobelin et gobelours sont les gobelinoïdes. L’orque et le kobold forment d’autres peuples.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquels de ces monstres sont d’alignement loyal mauvais ? (plusieurs bonnes réponses)',['Hobgobelin','Kobold','Sahuagin'],['Gobelin','Orque'],'Hobgobelin, kobold et sahuagin sont loyaux mauvais ; le gobelin est neutre mauvais, l’orque chaotique mauvais.',MM+', entrées correspondantes')
M(2,'Dans D&D 5e, lesquels de ces peuples sont reptiliens ou amphibiens ? (plusieurs bonnes réponses)',['Homme-lézard','Kobold','Yuan-ti'],['Gnoll','Orque'],'Hommes-lézards, kobolds et yuan-ti ont des traits de reptiles ; gnolls et orques non.',MM+', entrées correspondantes')
O(3,'Classe ces humanoïdes par FP croissant.',['Kobold','Gobelin','Orque','Gobelours','Abomination yuan-ti'],'FP : kobold 1/8, gobelin 1/4, orque 1/2, gobelours 1, abomination yuan-ti 7.',MM+', blocs de caractéristiques')
O(3,'Classe ces humanoïdes par points de vie moyens croissants.',['Kobold','Gobelin','Orque','Gnoll','Gobelours'],'PV moyens : kobold 5, gobelin 7, orque 15, gnoll 22, gobelours 27.',MM+', blocs de caractéristiques')
A(2,'Associe chaque peuple à son dieu.',[('Orques','Gruumsh'),('Gobelinoïdes','Maglubiyet'),('Kobolds','Kurtulmak'),('Gnolls','Yeenoghu')],'Gruumsh règne sur les orques, Maglubiyet sur les gobelinoïdes, Kurtulmak sur les kobolds, Yeenoghu sur les gnolls.',MM+' et Volo’s Guide to Monsters (2016)')
A(2,'Associe chaque monstre à son trait de combat.',[('Gobelin','Fuite agile'),('Orque','Agressif'),('Kobold','Tactique de meute'),('Hobgobelin','Avantage martial')],'Chaque monstre a un trait qui définit son style : fuite, charge, meute ou discipline.',MM+', entrées correspondantes')
W(1,['Je suis petit, vert et malin.','Je me déplace avec agilité et je me cache en un clin d’œil.','Je sers souvent un hobgobelin ou un gobelours.'],'Gobelin',['Kobold','Orque','Hobgobelin'],'Le gobelin est un petit gobelinoïde rusé, qui peut se désengager ou se cacher en action bonus.',MM+', entrée « Gobelin »')
W(2,['Je suis grand, poilu et massif.','Mes proches me croient lourd, mais je suis un tueur furtif.','J’attaque par surprise pour infliger de lourds dégâts.'],'Gobelours',['Hobgobelin','Gnoll','Orque'],'Le gobelours profite de son Attaque surprise pour frapper plus fort.',MM+', entrée « Gobelours »')
W(2,['Je suis un petit humanoïde reptilien.','Seul je suis peureux, mais en groupe je suis redoutable.','Je sers les dragons et le soleil me gêne.'],'Kobold',['Gobelin','Homme-lézard','Bullywug'],'Le kobold combat en meute, vénère les dragons et craint la lumière du jour.',MM+', entrée « Kobold »')
save('gobelinoides-humanoides','gob')
